    protected boolean isIncludedByTradeAgreement(GUPPriceEngineAbstractLine _line,
        SalesTable _salesTable, SalesLine _salesLine)
    {
        GUPPriceEngineAttributeGroupObject headerAttributeGroup = _line.parmHeaderAttribute();
        if (headerAttributeGroup != null && headerAttributeGroup.isExcluded(_salesTable.CustAccount))
        {
            return false;
        }

        GUPPriceEngineAttributeGroupObject lineAttributeGroup = _line.parmLineAttribute();
        if (lineAttributeGroup != null && lineAttributeGroup.isExcluded(_salesLine.ItemId))
        {
            return false;
        }

        return true;
    }
